insert into analytics.semantic_rules(rule_id,rule_name,required_behavior,example)
values
('SEM-001','0 ≠ NOT READY','If denominator/source is incomplete, return NOT_READY/null plus reason, not 0%','D30 retention before any D30-eligible cohort'),
('SEM-002','Current Status ≠ Historical Funnel','Historical conversion must use transition/event timestamps','Current STARTED candidate should still count as historical LEAD cohort'),
('SEM-003','Cohort Eligibility','Retention denominator includes only records old enough to reach milestone','D30 denominator: verified start_date <= as_of-30d'),
('SEM-004','One KPI one definition','KPI ID has one canonical numerator/denominator/time grain','No duplicate Collected with different cash basis'),
('SEM-005','Finance evidence-backed','Official finance KPI comes from reconciled operational/accounting records','COLLECTED requires payment evidence/match'),
('SEM-006','Attribution evidence-backed','Partner/source KPI uses approved attribution evidence','Partner replying in thread is not attribution'),
('SEM-007','Late-arriving facts','Recompute affected historical period/cohort when stronger source arrives','Backfilled start confirmation updates start cohort'),
('SEM-008','Timezone','Business reporting timezone Asia/Bangkok','Daily bucket closes at Bangkok local date'),
('SEM-009','Data freshness visible','Dashboard displays freshness/as-of and quality badge','As of 2026-08-29 23:30 ICT'),
('SEM-010','Drill-through','KPI should resolve to underlying Entity IDs/evidence where authorized','Collected amount → revenue/payment/evidence records')
insert into analytics.dq_gate_catalog(gate_id,kpi_domain,check_description,severity_if_fail,behavior_if_fail,owner_role,architecture_status)
values
('DQG-001','Funnel','Stage-transition history exists for selected period','HIGH','Rate = NOT_READY; snapshot counts may still show','Data Audit','PLANNED'),
('DQG-002','Appointment/No-show','Appointment date and standardized outcome present','HIGH','Show count quality warning / block rate','Candidate Ops','PLANNED'),
('DQG-003','Retention','Start date + milestone outcome + cohort eligibility available','HIGH','Retention = NOT_READY','Candidate Ops','PLANNED'),
('DQG-004','Finance Collected','Reliable payment evidence and match exist','CRITICAL','Exclude from official Collected','Finance','ACTIVE RULE'),
('DQG-005','Partner KPI','Attribution evidence resolved','HIGH','Exclude unresolved from partner performance; show unresolved count','Data Audit','ACTIVE RULE'),
('DQG-006','Client Fill','Confirmed requested headcount exists','HIGH','Fill Rate = NOT_READY for job/client period','Client Sales','PLANNED'),
('DQG-007','Accounting','Posted journal batches balanced','CRITICAL','Accounting dashboard red/blocked','Finance','ACTIVE RULE'),
('DQG-008','Freshness','Source/mart refreshed within required window','MEDIUM/HIGH','Show STALE badge; alerts if critical','Data Audit','PLANNED'),
('DQG-009','Files','Evidence File Registry link/object/source status valid','HIGH','Evidence-based KPI flagged','Data Audit','PLANNED'),
('DQG-010','Privacy','Dashboard role authorized for fields displayed','CRITICAL','Deny query/render','Architect/Data Audit','PLANNED')
