on conflict (kpi_id) do update set domain=excluded.domain,kpi_name=excluded.kpi_name,kpi_class=excluded.kpi_class,definition=excluded.definition,numerator=excluded.numerator,denominator=excluded.denominator,time_grain=excluded.time_grain,primary_source=excluded.primary_source,required_fields=excluded.required_fields,eligibility_filter=excluded.eligibility_filter,result_type=excluded.result_type,not_ready_rule=excluded.not_ready_rule,owner_role=excluded.owner_role,dashboard=excluded.dashboard,priority=excluded.priority,updated_at=now();

on conflict (rule_id) do update set rule_name=excluded.rule_name,required_behavior=excluded.required_behavior,example=excluded.example;

on conflict (gate_id) do update set kpi_domain=excluded.kpi_domain,check_description=excluded.check_description,severity_if_fail=excluded.severity_if_fail,behavior_if_fail=excluded.behavior_if_fail,owner_role=excluded.owner_role,architecture_status=excluded.architecture_status,updated_at=now();

on conflict (test_id) do update set scenario=excluded.scenario,expected_behavior=excluded.expected_behavior,critical=excluded.critical,updated_at=now();